def get_message_from_template(
    template_name: str, name: str, args: tuple[(Any, ...)]
) -> str:
    d = render_template(template_name).get("messages", {})
    msg = d.get(name) or name.lower().replace("_", " ")

    if msg and args:
        return msg % args
    else:
        return msg


